<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { formatBRL, sumCents } from '../../../lib/money'
import { ChevronRight, Search, Truck, UserRound, X } from 'lucide-vue-next'

type Partner = { id: number; type: 'Fornecedor' | 'Mão de obra'; name: string; displayName: string; legalName: string; phone: string; cnpj: string; identifiers: string[]; paidCents: number; openCents: number; last: string }
const partners = ref<Partner[]>([
  { id: 10, type: 'Fornecedor', name: 'Posto Exemplo', displayName: 'Posto Exemplo', legalName: 'Posto Exemplo Ltda.', phone: '(11) 98888-4410', cnpj: '00.000.000/0001-10', identifiers: [], paidCents: 486500, openCents: 72800, last: '14 out 2026' },
  { id: 11, type: 'Mão de obra', name: 'Bruno Prestador', displayName: 'Bruno Prestador', legalName: '', phone: '(11) 97777-1120', cnpj: '', identifiers: [], paidCents: 274000, openCents: 0, last: '09 out 2026' },
  { id: 12, type: 'Fornecedor', name: 'Fornecedor Exemplo 2', displayName: 'Fornecedor Exemplo 2', legalName: '', phone: '(11) 96610-2830', cnpj: '00.000.000/0001-12', identifiers: [], paidCents: 163400, openCents: 36800, last: '07 out 2026' },
  { id: 13, type: 'Mão de obra', name: 'Prestador Teste 2', displayName: 'Prestador Teste 2', legalName: '', phone: '(11) 95543-1001', cnpj: '', identifiers: [], paidCents: 98500, openCents: 15200, last: '01 out 2026' },
])
const router = useRouter()
const route = useRoute()
const typeFilter = ref<'Todos' | Partner['type']>('Todos')
const typeFilters = ['Todos', 'Fornecedor', 'Mão de obra'] as const
const query = ref('')
const onlyOpen = ref(false)
const shown = computed(() => partners.value.filter(p => (typeFilter.value === 'Todos' || p.type === typeFilter.value) && (!onlyOpen.value || p.openCents > 0) && `${p.name} ${p.displayName} ${p.legalName} ${p.phone} ${p.cnpj}`.toLocaleLowerCase('pt-BR').includes(query.value.toLocaleLowerCase('pt-BR'))))
const totalOpen = computed(() => sumCents(partners.value.map(p => p.openCents)))
const active = ref<Partner | null>(null)
const details = ref<HTMLDialogElement | null>(null)
const editor = ref<HTMLDialogElement | null>(null)
const editingId = ref<number | null>(null)
const notice = ref('')
const formError = ref('')
const draft = ref({ type: 'Fornecedor' as Partner['type'], name: '', displayName: '', legalName: '', phone: '', cnpj: '' })
function close(dialog: HTMLDialogElement | null) { dialog?.close() }
function openDetails(p: Partner) { active.value = p; details.value?.showModal() }
async function openEditor(p?: Partner) {
  formError.value = ''
  editingId.value = p?.id ?? null
  draft.value = p ? { type: p.type, name: p.name, displayName: p.displayName, legalName: p.legalName, phone: p.phone, cnpj: p.cnpj } : { type: 'Fornecedor', name: '', displayName: '', legalName: '', phone: '', cnpj: '' }
  await nextTick(); editor.value?.showModal()
}
function save() {
  const name = draft.value.name.trim(); const phone = draft.value.phone.trim()
  if (!name) { formError.value = 'Informe o nome do parceiro para continuar.'; return }
  if (editingId.value) {
    const p = partners.value.find(item => item.id === editingId.value)
    if (p) Object.assign(p, draft.value, { name })
    notice.value = `${name} atualizado na prévia.`
  } else {
    partners.value.unshift({ id: Math.max(...partners.value.map(p => p.id)) + 1, ...draft.value, name, identifiers: [], paidCents: 0, openCents: 0, last: 'Sem movimentação' })
    notice.value = `${name} adicionado. Movimentações começam sem saldo até serem registradas.`
  }
  formError.value = ''
  editor.value?.close()
}
onMounted(() => {
  const partner = partners.value.find(item => item.id === Number(route.query.partnerId))
  if (partner) openDetails(partner)
})
</script>

<template>
  <main class="preview-page partners-preview">
    <p class="preview-eyebrow">Cadastros · quem fornece e executa</p>
    <div class="preview-heading"><div><h1>Parceiros</h1><p class="preview-subtitle">Fornecedores e mão de obra com seus contatos e movimentações registradas.</p></div><button class="preview-button-primary" @click="openEditor()"><UserRound :size="18" aria-hidden="true" /> Novo parceiro</button></div>
    <div v-if="notice" class="preview-notice" role="status">{{ notice }} <button @click="notice = ''">Fechar</button></div>
    <section class="partner-summary"><article><span>Em aberto</span><strong>{{ formatBRL(totalOpen) }}</strong><small>Movimentações de exemplo ainda não quitadas</small></article><article><span>Fornecedores</span><strong>{{ partners.filter(p => p.type === 'Fornecedor').length }}</strong><small>Vidro, ferragens e materiais</small></article><article><span>Mão de obra</span><strong>{{ partners.filter(p => p.type === 'Mão de obra').length }}</strong><small>Instalação e serviços</small></article></section>
    <section class="preview-surface partner-toolbar"><label class="preview-search"><Search :size="18" aria-hidden="true" /><input v-model="query" aria-label="Buscar parceiros" placeholder="Buscar nome, telefone ou serviço" /></label><div class="partner-filters" aria-label="Filtrar parceiros"><button v-for="item in typeFilters" :key="item" type="button" class="preview-chip" :class="{ 'is-active': typeFilter === item }" :aria-pressed="typeFilter === item" @click="typeFilter = item">{{ item }}</button><button type="button" class="preview-chip open-filter" :class="{ 'is-active': onlyOpen }" :aria-pressed="onlyOpen" @click="onlyOpen = !onlyOpen">{{ onlyOpen ? 'Com valor em aberto · ativo' : 'Com valor em aberto' }}</button></div></section>
    <div class="partner-section-heading"><h2>Lista de parceiros</h2><span>{{ shown.length }} cadastros <small>· dados de exemplo</small></span></div>
    <section v-if="shown.length" class="partner-list"><button v-for="p in shown" :key="p.id" class="partner-row" @click="openDetails(p)"><span class="partner-mark" :class="p.type === 'Fornecedor' ? 'supplier' : 'labor'"><Truck v-if="p.type === 'Fornecedor'" :size="21" aria-hidden="true" /><UserRound v-else :size="21" aria-hidden="true" /></span><span class="partner-main"><strong>{{ p.displayName || p.name }}</strong><span>{{ p.phone || 'Telefone não informado' }}<template v-if="p.legalName"> · {{ p.legalName }}</template></span></span><span class="partner-kind" :class="p.type === 'Fornecedor' ? 'supplier' : 'labor'">{{ p.type }}</span><span class="partner-money"><strong>{{ formatBRL(p.openCents) }}</strong><small>{{ p.openCents ? 'em aberto' : 'sem valor em aberto' }}</small></span><ChevronRight :size="20" class="partner-chevron" aria-hidden="true" /></button></section>
    <div v-else class="preview-empty"><h2>Nenhum parceiro encontrado</h2><p>Experimente outro nome ou altere os filtros.</p><button class="preview-button" @click="query = ''; onlyOpen = false; typeFilter = 'Todos'">Limpar filtros</button></div>

    <dialog ref="details" class="preview-dialog partner-dialog" aria-labelledby="partner-details-title" @click="($event.target as HTMLElement).tagName === 'DIALOG' && close(details)"><template v-if="active"><header class="dialog-heading"><div><p class="preview-eyebrow">{{ active.type }} · parceiro #{{ active.id }}</p><h2 id="partner-details-title">{{ active.displayName || active.name }}</h2><p v-if="active.legalName" class="preview-subtitle">{{ active.legalName }}</p></div><button class="dialog-close" aria-label="Fechar detalhes do parceiro" @click="close(details)"><X :size="20" /></button></header><div class="partner-detail-content"><section class="partner-contact"><h3>Contato e identificação</h3><p><strong>Telefone</strong>{{ active.phone || 'Não informado' }}</p><p><strong>CNPJ</strong>{{ active.cnpj || 'Não informado' }}</p><p v-for="(identifier,index) in active.identifiers" :key="index"><strong>Identificador</strong>{{ identifier }}</p></section><section class="partner-finance"><h3>Movimentações registradas</h3><div class="finance-line"><span>Pagamentos feitos</span><strong>{{ formatBRL(active.paidCents) }}</strong></div><div class="finance-line finance-open"><span>Valor em aberto</span><strong>{{ formatBRL(active.openCents) }}</strong></div><p>Último registro: {{ active.last }}</p><small>Os valores são fictícios. Confira o lançamento e o destinatário antes de pagar.</small></section><button class="preview-button finance-link" @click="close(details); router.push({ name: 'Ledger', query: { ...route.query, partnerId: String(active.id) } })">Ir para Financeiro</button></div><footer class="dialog-actions"><button class="preview-button" @click="openEditor(active)">Editar parceiro</button><button class="preview-button-primary" @click="close(details)">Fechar detalhes</button></footer></template></dialog>
    <dialog ref="editor" class="preview-dialog partner-editor" aria-labelledby="partner-editor-title"><form class="editor-form" @submit.prevent="save"><header class="dialog-heading"><div><p class="preview-eyebrow">{{ editingId ? 'Atualizar cadastro' : 'Novo cadastro' }}</p><h2 id="partner-editor-title">{{ editingId ? 'Editar parceiro' : 'Cadastrar parceiro' }}</h2><p class="preview-subtitle">Os campos representam dados de cadastro disponíveis na prévia.</p></div><button type="button" class="dialog-close" aria-label="Fechar cadastro de parceiro" @click="close(editor)"><X :size="20" /></button></header><p v-if="formError" class="partner-form-error" role="alert">{{ formError }}</p><div class="partner-fields"><label class="preview-form-field">Tipo de parceiro<select v-model="draft.type"><option>Fornecedor</option><option>Mão de obra</option></select></label><label class="preview-form-field">Nome de pessoa ou empresa<input v-model="draft.name" required maxlength="90" placeholder="Ex.: Vidraçaria Central" /></label><label class="preview-form-field">Nome de exibição (opcional)<input v-model="draft.displayName" maxlength="90" placeholder="Como aparece nas listas" /></label><label class="preview-form-field">Razão social (opcional)<input v-model="draft.legalName" maxlength="120" placeholder="Nome jurídico" /></label><label class="preview-form-field">Telefone <small>Opcional</small><input v-model="draft.phone" type="tel" placeholder="(11) 99999-9999" /></label><label class="preview-form-field">CNPJ (opcional)<input v-model="draft.cnpj" maxlength="24" placeholder="00.000.000/0001-00" /></label><p class="partner-form-note">Atividade e observações não fazem parte do cadastro suportado. Novos parceiros começam sem movimentações.</p></div><footer class="dialog-actions"><button type="button" class="preview-button" @click="close(editor)">Cancelar</button><button type="submit" class="preview-button-primary">{{ editingId ? 'Salvar alterações' : 'Adicionar parceiro' }}</button></footer></form></dialog>
  </main>
</template>

<style scoped>
