;color:#24302b;font-size:28px;cursor:pointer}.partner-detail-content{display:grid;gap:15px;padding:21px 25px}.partner-detail-content h3{margin:0 0 12px;font:600 19px var(--font-verly-display)}.partner-contact{padding:16px;border-radius:12px;background:#f3f5f4}.partner-contact p{display:grid;gap:3px;margin:0 0 12px;color:#35413d;font-size:16px}.partner-contact p strong{color:#68746f;font-size:15px}.partner-finance{padding:16px;border:1px solid #dce2df;border-radius:12px}.finance-line{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #e3e8e5;color:#40504a;font-size:16px}.finance-line strong{font:600 16px var(--font-verly-mono)}.finance-open strong{color:#a84f06}.partner-finance>p{margin:12px 0 8px;color:#5d6964;font-size:15px}.partner-finance>small{display:block;color:#65716c;font-size:15px;line-height:1.4}.partner-payment-callout{display:grid;gap:4px;padding:13px 15px;border-left:4px solid #a84f06;border-radius:8px;background:#fbe8cf;color:#733803;font-size:16px}.partner-payment-callout span{font-size:15px;line-height:1.4}.finance-link{justify-self:start}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;padding:15px 25px 22px;border-top:1px solid #e0e5e2}.partner-editor{width:min(600px,calc(100vw - 32px))}.editor-form{display:block}.partner-fields{display:grid;gap:13px;padding:20px 25px}.preview-form-field{display:grid;gap:6px;color:#34413c;font-size:15px;font-weight:600}.preview-form-field input,.preview-form-field select,.preview-form-field textarea{width:100%;min-height:46px;padding:10px 12px;border:1px solid #9eada7;border-radius:8px;background:#fff;color:#141a1f;font:16px var(--font-verly-body)}.preview-form-field textarea{resize:vertical}.partner-form-note{margin:0;padding:10px 12px;border-radius:8px;background:#edf6ef;color:#315c38;font-size:15px}.preview-empty{padding:36px;border:1px dashed #aebbb5;border-radius:14px;text-align:center}.preview-empty h2{font:600 22px var(--font-verly-display)}.preview-empty p{color:#596661;font-size:16px}.preview-notice{display:flex;justify-content:space-between;gap:12px;margin:0 0 14px;padding:12px 15px;border-left:4px solid #1e7a3c;border-radius:8px;background:#edf6ef;color:#245631;font-size:15px}.preview-notice button{border:0;background:none;color:inherit;font:600 15px var(--font-verly-body);text-decoration:underline;cursor:pointer}
